import pathlib,sqlite3

def init(path):
    with sqlite3.connect(path,isolation_level=None) as db:
        db.execute("PRAGMA journal_mode=WAL")
        db.execute("PRAGMA synchronous=FULL")
        db.executescript("CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY,payload BLOB NOT NULL,done INTEGER NOT NULL); CREATE TABLE IF NOT EXISTS effects(id TEXT PRIMARY KEY,payload BLOB NOT NULL);")

def apply(path,job,payload,hook=None,page_limit=None):
    halt=pathlib.Path(str(path)+".halt")
    if halt.exists(): raise RuntimeError("ledger halted; retain database and evidence")
    db=sqlite3.connect(path,timeout=0.15,isolation_level=None)
    try:
        db.execute("PRAGMA synchronous=FULL")
        if page_limit is not None:
            if not isinstance(page_limit,int) or page_limit<1: raise ValueError("invalid private page limit")
            db.execute("PRAGMA max_page_count="+str(page_limit))
        db.execute("BEGIN IMMEDIATE")
        if halt.exists(): raise RuntimeError("ledger halted")
        old=db.execute("SELECT payload,done FROM jobs WHERE id=?",(job,)).fetchone()
        if old:
            if old[0]!=payload: raise ValueError("same identity different payload")
            if old[1]!=1: raise RuntimeError("inconsistent ledger")
            db.execute("COMMIT")
            return "already"
        db.execute("INSERT INTO jobs VALUES(?,?,0)",(job,payload))
        db.execute("INSERT INTO effects VALUES(?,?)",(job,payload))
        db.execute("UPDATE jobs SET done=1 WHERE id=?",(job,))
        if hook: hook("before_commit")
        db.execute("COMMIT")
        if hook: hook("after_commit")
        return "committed"
    except sqlite3.Error as exc:
        if db.in_transaction: db.execute("ROLLBACK")
        code=getattr(exc,"sqlite_errorcode",0)&255
        if code not in (sqlite3.SQLITE_BUSY,sqlite3.SQLITE_LOCKED):
            halt.write_text(str(getattr(exc,"sqlite_errorname","SQLITE_ERROR")),encoding="utf8")
        raise
    except BaseException:
        if db.in_transaction: db.execute("ROLLBACK")
        raise
    finally:
        db.close()
